import 'package:flutter/material.dart';import 'package:sizer/sizer.dart';class ScreenCardPadding extends StatelessWidget {  final Widget child;  final Color? color;  const ScreenCardPadding({super.key, required this.child, this.color});  @override  Widget build(BuildContext context) {    return Container(      decoration: BoxDecoration(        color: color ?? Colors.white,        borderRadius: BorderRadius.circular(4.w),        boxShadow: [          BoxShadow(            color: Colors.black.withValues(alpha: 0.05),            blurRadius: 10,            offset: Offset(0, 4),          ),        ],      ),      padding: EdgeInsets.symmetric(horizontal: 3.w, vertical: 2.h),      child: child,    );  }}